    [DefaultExecutionOrder(-220)]public sealed class PlanetShipValidation:MonoBehaviour
    {
        [Serializable]sealed class Report{public string status="PASS",error="",memoryScope="Unity tracked allocation/reservation, not total VRAM";public List<string> checks=new List<string>();public int colliders,rebases;public Vector3 lastFeet,cameraLocal;public float worstLocalDrift,maximumCameraOffset;public double movementMedianMs,movementP95Ms;public long allocatedBytes,reservedBytes;}
        readonly Report report=new Report();readonly List<double> movement=new List<double>();PlanetDevelopment world;PlanetSpacecraft ship;PlanetFirstPersonController player;string output;RenderTexture target,hudTarget,hudComposite;Material hudMaterial;
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Install(){if(!Application.isEditor&&Array.IndexOf(Environment.GetCommandLineArgs(),"-planet-ship-validation")>=0)new GameObject("Ship interaction regression").AddComponent<PlanetShipValidation>();}
        void Awake(){var args=Environment.GetCommandLineArgs();output=args[Array.IndexOf(args,"-planet-output")+1];Directory.CreateDirectory(output);world=FindAnyObjectByType<PlanetDevelopment>();world.currentRtsContent=true;world.sessionMode=PlanetGameMode.Rts;world.ambientZombies=0;world.requestedCapacity=4096;world.configuredRadius=120000;Application.targetFrameRate=-1;QualitySettings.vSyncCount=0;Time.captureDeltaTime=1f/60;}
