        IEnumerator Guard(){var run=Run();while(true){object next;try{if(!run.MoveNext())break;next=run.Current;}catch(Exception e){report.status="FAIL";report.error=e.ToString();UnityEngine.Debug.LogException(e);break;}yield return next;}if(player!=null)report.lastFeet=player.ShipLocalPosition;report.allocatedBytes=Profiler.GetTotalAllocatedMemoryLong();report.reservedBytes=Profiler.GetTotalReservedMemoryLong();movement.Sort();if(movement.Count>0){report.movementMedianMs=movement[movement.Count/2];report.movementP95Ms=movement[(int)((movement.Count-1)*.95)];}File.WriteAllText(Path.Combine(output,"validation.json"),JsonUtility.ToJson(report,true));Time.captureDeltaTime=0;Application.Quit(report.status=="PASS"?0:1);}
